WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM transactions), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), gaps_2 AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session_2 FROM sessionized), sessions_transactions AS (SELECT id, account_id, txn_time, merchant, is_flagged, is_new_session, session_id, SUM(is_new_session_2) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps_2), scored AS (SELECT id, merchant, is_flagged, session_id, session_no, SUM(session_id) OVER (PARTITION BY merchant ORDER BY session_no, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_session_id, AVG(session_id) OVER (PARTITION BY merchant ORDER BY session_no, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_session_id, COUNT(session_id) OVER (PARTITION BY merchant ORDER BY session_no, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_session_id, ROW_NUMBER() OVER (ORDER BY session_id DESC, id) AS seq_no FROM sessions_transactions), metrics AS (SELECT *, SUM(session_id) OVER w_grp AS last3_sum_session_id, COUNT(session_id) OVER w_grp AS last3_count_session_id, MIN(session_id) OVER w_grp AS last3_min_session_id, MAX(session_id) OVER w_grp AS last3_max_session_id FROM scored WHERE session_no BETWEEN 6 AND 7 WINDOW w_grp AS (PARTITION BY merchant ORDER BY session_no, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), metrics_transactions AS (SELECT id, session_id, last4_sum_session_id, last4_avg_session_id, last3_count_session_id, NTILE(5) OVER w_grp AS session_id_bucket, NTILE(3) OVER w_grp AS session_id_bucket_2 FROM metrics WINDOW w_grp AS (PARTITION BY merchant ORDER BY session_id, id)), scored_transactions AS (SELECT *, LAST_VALUE(last4_sum_session_id) IGNORE NULLS OVER (ORDER BY last4_sum_session_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_last4_sum_session_id, SUM(session_id_bucket) OVER (ORDER BY session_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_session_id_bucket, DENSE_RANK() OVER (ORDER BY last4_avg_session_id NULLS LAST) AS last4_avg_session_id_dense_rank FROM metrics_transactions) SELECT session_id, COUNT(*) AS num_rows, PERCENTILE_APPROX(session_id, 0.9) AS session_id_p90, SUM(session_id_bucket) AS total_session_id_bucket, COUNT(*) AS cnt FROM scored_transactions GROUP BY session_id
